// Fails when app components use raw colors or arbitrary sizes instead of design tokens.
// src/components/ui is generated by shadcn/ui and kept as delivered.
import { readdirSync, readFileSync, statSync } from "node:fs";
import { join, relative } from "node:path";

const root = new URL("../src", import.meta.url).pathname;
const skip = [join(root, "components/ui")];
const rules = [
  {
    name: "raw color",
    pattern: /#[0-9a-fA-F]{3,8}\b|\b(?:rgb|rgba|hsl|hsla|oklch|oklab)\(/g,
  },
  { name: "arbitrary value", pattern: /\b[\w:-]+-\[[^\]]+\]/g },
];

function* files(dir) {
  for (const name of readdirSync(dir)) {
    const path = join(dir, name);
    if (skip.includes(path)) continue;
    if (statSync(path).isDirectory()) yield* files(path);
    else if (/\.(tsx|ts)$/.test(name) && !/\.test\.tsx?$/.test(name))
      yield path;
  }
}

const problems = [];
for (const file of files(root)) {
  readFileSync(file, "utf8")
    .split("\n")
    .forEach((line, index) => {
      for (const { name, pattern } of rules) {
        for (const match of line.matchAll(pattern)) {
          problems.push(
            `${relative(process.cwd(), file)}:${index + 1}  ${name}: ${match[0]}`,
          );
        }
      }
    });
}

if (problems.length > 0) {
  console.error(
    `Use design tokens from src/index.css (see DESIGN.md):\n${problems.join("\n")}`,
  );
  process.exit(1);
}
console.log("Design tokens: no raw colors or arbitrary values.");
